function renderReserved(){const known=[['2025-06-1','2025 年 6 月 · 第一套','29989516'],['2025-06-2','2025 年 6 月 · 第二套','29989517'],['2025-12-1','2025 年 12 月 · 第一套','31694682'],['2025-12-2','2025 年 12 月 · 第二套','31694683'],['2026-06-1','2026 年 6 月 · 第一套','33551172'],['2026-06-2','2026 年 6 月 · 第二套','33551173']];return titleBlock('整卷保留区','等你准备好了，再完整听一套。','RESERVED FOR YOUR MOCK EXAM','<button data-action="import-audio">导入整卷音频</button>')+'<div class="notice">这里与日常训练隔离。仅在你主动播放时加载整卷；不显示文章主题、原文或答案。外部入口尚未试听核验，不能视为已下载。</div>'+known.map(([id,title,program])=>{const local=reservedFiles.find(f=>f.id===id);return '<article class="card reserved-entry"><div><h3>'+title+'</h3><p>'+(local?'本机已导入音频':'仅定位公开入口')+' · '+(state.reservedPlayed.includes(id)?'已整卷听完':'未完成')+'</p></div>'+(local?'<button class="primary" data-reserved="'+id+'">播放整卷</button>':'<a href="https://www.qtfm.cn/channels/284150/programs/'+program+'/" target="_blank" rel="noopener noreferrer">打开整卷入口 ↗</a>')+'</article>';}).join('')+(activeReserved?'<div class="card resource-block"><h2 id="reserved-now">正在播放整卷</h2><input class="track-input" id="seek" type="range" min="0" max="1000" value="0" aria-label="整卷进度"><div class="time-row"><span id="play-time"></span><span id="duration"></span></div><button data-action="play-toggle" id="play-toggle">暂停 / 继续</button><button data-action="reserved-restart">从头开始</button><button data-action="stop">停止</button><p>保留原始考试顺序与停顿，默认 1.0×，结束后停止。</p></div>':'')+'<p class="res-status">2026 年 12 月：尚未举行，待考试后补充真实资料。</p>';}
function renderResources(){const paths=allPaths();const offline=paths.length&&paths.every(p=>storedPaths.has(p));return titleBlock('资源与数据','你拥有自己的材料，也拥有自己的学习记录。','YOUR DATA, ON THIS DEVICE')+'<div class="resource-grid"><section class="card resource-block"><h2>离线原声</h2><p>当前题库包含 '+paths.length+' 个音频文件，'+paths.filter(p=>storedPaths.has(p)).length+' 个可从本机离线读取。<br><strong>'+(offline?'当前题库全部练习音频可离线读取':'尚未完整保存到本机')+'</strong></p><button class="primary" data-action="cache-all">保存当前题库供离线使用</button><button data-action="import-folder">导入 audio 文件夹</button><p id="cache-progress">保留本地服务器运行时，断开互联网也能直接播放随包音频。安装离线缓存后，可在同一网址重新打开；不要使用隐身模式。</p></section><section class="card resource-block"><h2>导入真题资源包</h2><p>导入经过校准的 catalog.json，再导入对应 audio 文件夹。MP3、WAV 等音频可以单独导入。PDF、TXT 保留为本地参考材料，不能自动假装变成完整试题。</p><button data-action="import-json">导入题库 JSON</button><button data-action="import-audio">导入音频</button><button data-action="schema">查看数据格式</button><p>批量识别、句词对齐、去重、裁切工具位于 tools 目录。自动识别结果始终标记为待校准。</p></section><section class="card resource-block"><h2>学习记录备份</h2><p>记录先保存在此浏览器。可选择在「账号 / 同步」启用云同步，也可下载备份。</p><p class="backup-summary">'+summaryText(backupSummary(state))+'</p>'+(location.hostname==='cet6-listening-lab.guxn.chatgpt.site'?'<details><summary>旧网址的记录怎么找？</summary><p>旧网址联网会跳转到这里，跳转后只显示新网址的记录。如果手里有旧版导出的备份，可以直接导入。没有备份时，可在原平板、原浏览器断网后尝试打开原来的离线入口；只有仍停留在旧网址并看得到旧记录，才能从旧版导出。</p></details>':'')+'<div class="backup-buttons"><button class="primary" data-action="copy-backup">复制学习记录</button><button data-action="backup-text">粘贴并合并</button><button data-action="export-backup">下载备份 JSON</button><button data-action="import-backup">导入备份文件</button></div><button data-action="export-data">导出当前题库 / 校准结果</button></section><section class="card resource-block"><h2>数据质量</h2><p>'+db.exams.length+' 套已导入试卷 · '+resources().length+' 篇 · '+resources().reduce((n,p)=>n+p.questions.length,0)+' 题。<br>英文原文来自公开真题资料；译文为第三方辅助译文。时间戳由真实录音自动对齐生成，尚未完成人工试听验收。</p><button data-action="quality">运行完整性检查</button><button data-action="answer-audit">查看答案复核</button><button data-action="audio-audit">查看音频巡检</button><button data-action="sources">素材来源</button>'+(hasLegacyRecordings?'<p><button data-action="record-list">导出旧录音</button></p>':'')+'</section></div><div class="section-title"><h2>2017—2024 资料入口</h2><small>下列链接不是已导入题库，完整性仍需核验</small></div><div class="card table-wrap"><table class="data-list"><thead><tr><th>年份</th><th>资料入口</th><th>本站导入状态</th></tr></thead><tbody>'+Array.from({length:8},(_,i)=>2017+i).map(y=>'<tr><td>'+y+'</td><td><a href="https://english-exam.lazynote.cn/cet6/sections/listening/" target="_blank" rel="noopener">听力目录 ↗</a>　'+(y>=2019?'<a href="https://www.wehuster.com/cet6" target="_blank" rel="noopener">整卷资料 ↗</a>':'')+'</td><td>'+ (exams().some(e=>e.year===y)?exams().filter(e=>e.year===y).length+' 套 · 部分完整':'尚未导入')+'</td></tr>').join('')+'</tbody></table></div>';}
