function normalizeRoute(r){
 const to=Object.hasOwn(labels,r?.view)?r.view:'library',f={...defaultFilters,...r?.f},ids=resources();
 if(!exams().some(e=>String(e.year)===f.year))f.year='all';
 if(f.exam!=='all'&&!exams().some(e=>e.examId===f.exam&&String(e.year)===f.year))f.exam='all';
 const id=to==='study'?(ids.some(p=>p.passageId===r?.id)?r.id:ids.some(p=>p.passageId===currentId)?currentId:ids[0]?.passageId):null;
 return {view:to,id,tab:to==='study'&&Object.hasOwn(tabNames,r?.tab)?r.tab:to==='study'?'practice':null,f};
}
function routeHash(r){if(r.view==='study'&&r.id)return '#study/'+encodeURIComponent(r.id)+'/'+r.tab;if(r.view==='library'&&r.f.year!=='all')return '#library/'+r.f.year+(r.f.exam!=='all'?'/'+encodeURIComponent(r.f.exam):'');return '#'+r.view;}
function parseHash(){const [v,x,y]=location.hash.slice(1).split('/');if(!Object.hasOwn(labels,v))return null;if(v==='study')return normalizeRoute({view:v,id:x,tab:y});if(v==='library')return normalizeRoute({view:v,f:{year:x||'all',exam:y||'all'}});return normalizeRoute({view:v});}
let navFrame=0,navEpoch=0,navReady=false,restoringScroll=false;
function replaceRoute(){const h=history.state;if(!navReady||!h?.cet6||restoringScroll)return;const r=currentRoute();history.replaceState({...h,r,y:window.scrollY},'',routeHash(r));}
function applyRoute(r,y=0){
 r=normalizeRoute(r);const moved=r.view!==view||(r.view==='study'&&r.id!==currentId);
 if(moved||r.tab!==tab)setInkMode(false);
 if(!r.id||moved){engine.reset();activeReserved=null;activeWordKey=null;currentSentence=null;submitted=false;reviewSnapshot=null;evidenceId=null;showEvidence=false;}
 view=r.view;filterYear=r.f.year;filterExam=r.f.exam;filterType=r.f.type;filterStatus=r.f.status;sort=r.f.sort;query=r.f.query;
 if(r.id){currentId=r.id;tab=r.tab;if(tab==='review'&&!submitted)reviewSnapshot=firstReviewed(r.id);if(state.lastPassage!==r.id){state.lastPassage=r.id;save();}}
 $('#sidebar').classList.remove('open');const token=++navEpoch;restoringScroll=true;render();
 window.scrollTo(0,y);requestAnimationFrame(()=>{if(token!==navEpoch)return;window.scrollTo(0,y);restoringScroll=false;});
}
function moveTo(r,{replace=false}={}){
 const next=normalizeRoute(r),previous=history.state;
 if(JSON.stringify(currentRoute())===JSON.stringify(next)){$('#sidebar').classList.remove('open');return;}
 if(navFrame){cancelAnimationFrame(navFrame);navFrame=0;}restoringScroll=false;replaceRoute();
 const depth=previous?.cet6?(previous.depth||0):0;
 history[replace?'replaceState':'pushState']({cet6:1,depth:replace?depth:depth+1,r:next,y:0},'',routeHash(next));applyRoute(next);
}
function navigate(v,f){moveTo({view:v,f:f||(v===view?filters():defaultFilters)});}
function changeTab(k){moveTo({...currentRoute(),tab:k});}
function goBack(){if($('#modal').open){$('#modal').close();return;}if($('#sidebar').classList.contains('open')){$('#sidebar').classList.remove('open');return;}if(history.state?.cet6&&history.state.depth>0){history.back();return;}if(view!=='home')moveTo({view:view==='study'?'library':'home'},{replace:true});}
function openPassage(id,play=false,mode='practice'){if(!resources().some(p=>p.passageId===id))return;moveTo({view:'study',id,tab:mode,f:filters()});if(play)playMode('full').catch(handleError);}
function initNavigation(){
 history.scrollRestoration='manual';
 const h=history.state,target=h?.cet6?normalizeRoute(h.r):parseHash()||normalizeRoute({view:'home'});
 if(h?.cet6){navReady=true;applyRoute(target,Number(h.y)||0);return;}
 const base=normalizeRoute({view:'home'});history.replaceState({cet6:1,depth:0,r:base,y:0},'',routeHash(base));
 if(target.view==='study'){const list=normalizeRoute({view:'library'});history.pushState({cet6:1,depth:1,r:list,y:0},'',routeHash(list));}
 if(target.view!=='home')history.pushState({cet6:1,depth:target.view==='study'?2:1,r:target,y:0},'',routeHash(target));
 navReady=true;applyRoute(target);
}
async function playMode(mode,id){const p=passage();if(!p)return;activeReserved=null;engine.loop=mode==='sentence'?sentenceLoop:false;await engine.play(C.plan(p,mode,id),{passageId:p.passageId,kind:mode});}
async function playSentence(id){const p=passage(),s=p?.sentences.find(s=>s.sentenceId===id);if(!s)throw Error('找不到句子');currentSentence=id;engine.loop=sentenceLoop&&!continueSentence;await engine.play(C.sentencePlan(p,id,continueSentence,{leadIn:state.intensiveLead}),{passageId:p.passageId,kind:'sentence'});if(s.startTime===null)notify(continueSentence?'此句边界待校准，已从最近可用边界附近连续播放，起点可能包含上句尾部。':'此句边界待校准，正在播放附近原声，可能包含相邻语句。');}
const spanCache=new WeakMap();
function wordSpans(s){let spans=spanCache.get(s);if(!spans){spans=C.wordSpans(s);spanCache.set(s,spans);}return spans;}
let activeSentenceRow,activeWordNode;
function updateHighlight(p,r,pos){
 let sentence=null,word=null;
 if(p&&r&&engine.playing&&tab==='intensive'){
  const t=C.timelinePosition(p,r,pos),sameAudio=p.sentences.filter(s=>s.audioFile===t.audioFile);
  const matching=sameAudio.filter(s=>wordSpans(s).some(w=>w.startTime!==null&&t.time>=w.startTime&&t.time<w.endTime));
  sentence=matching.length===1?matching[0]:matching.length?null:sameAudio.find(s=>s.startTime!==null&&t.time>=s.startTime&&t.time<s.endTime);
  if(sentence){const matches=wordSpans(sentence).filter(w=>w.startTime!==null&&t.time>=w.startTime&&t.time<w.endTime);if(matches.length===1)word=matches[0];}
 }
 const row=sentence&&document.getElementById(sentence.sentenceId);
 const node=word&&row?.querySelector('[data-word="'+word.wordId+'"]');
 if(activeWordNode!==node){activeWordNode?.classList.remove('current');node?.classList.add('current');activeWordNode=node;}
 if(activeSentenceRow===row)return;
 activeSentenceRow?.classList.remove('active');activeSentenceRow=row;
 if(!row)return;
 row.classList.add('active');currentSentence=sentence.sentenceId;
 if(!inkMode&&Date.now()-lastManualScroll>7000){const rect=row.getBoundingClientRect(),sticky=$('#study-tabs');
  if(rect.bottom>innerHeight-40||rect.top<(sticky?.getBoundingClientRect().bottom||50))row.scrollIntoView({block:'center',behavior:'smooth'});
 }
}
function updateStudyMini(){
 const mini=$('#study-mini'),player=$('.player-card'),tabs=$('#study-tabs');
 if(!mini||!player||!tabs)return;
 // The same player stays controllable when its full card has scrolled off screen.
 const visible=player.getBoundingClientRect().bottom<=tabs.getBoundingClientRect().bottom+1;
 if(mini.hidden===visible)mini.hidden=!visible;
}
function updatePlayer(){
 const r=engine.queue[engine.index],pos=engine.position(),seek=$('#seek'),duration=r?r.endTime-r.startTime:passage()?.body?.endTime||0;
 const label=$('#player-level'),timeEl=$('#play-time'),dur=$('#duration'),cap=$('#player-caption');
 if(label)label.textContent=r?.label||'尚未播放';
 for(const btn of [$('#play-toggle'),$('#mini-play')])if(btn){btn.textContent=engine.playing?'Ⅱ':'▶';btn.setAttribute('aria-label',engine.playing?'暂停':'播放');}
 for(const btn of $$('[data-mode]')){const active=btn.dataset.mode===(engine.task?.kind||'full');btn.classList.toggle('active',active);btn.setAttribute('aria-pressed',String(active));}
 $('#vinyl')?.classList.toggle('playing',engine.playing);
 const fraction=r&&duration?(pos-r.startTime)/duration:0;
 if(seek&&document.activeElement!==seek)seek.value=Math.max(0,Math.min(1000,fraction*1000));
 if(timeEl)timeEl.textContent=time(r?pos-r.startTime:0);
 if(dur)dur.textContent=time(duration);
 if(cap)cap.textContent=r?(engine.ab?'A–B 区间循环 · ':engine.loop?'当前范围循环 · ':'')+(r.label||'原声')+(engine.queue.length>1?' · '+(engine.index+1)+' / '+engine.queue.length:''):'选择播放模式，从对应原声开始。';
 const bars=$$('.waveform b');bars.forEach((b,i)=>b.classList.toggle('past',i/bars.length<fraction));
 updateHighlight(view==='study'?passage():null,r,pos);
}
let lastPlayerPaint=0;
function animation(now){if(engine.playing&&now-lastPlayerPaint>=60){lastPlayerPaint=now;updatePlayer();}requestAnimationFrame(animation);}requestAnimationFrame(animation);
function download(name,obj,type='application/json'){const blob=obj instanceof Blob?obj:new Blob([typeof obj==='string'?obj:JSON.stringify(obj,null,2)],{type});const u=URL.createObjectURL(blob);const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}

