function selectedWord(key){const p=passage();for(const s of p?.sentences||[]){const w=C.wordSpans(s).find(w=>w.wordId===key);if(w)return {s,w};}return {};}
function openWord(key){activeWordKey=key;const {s,w}=selectedWord(key);if(!w)return;currentSentence=s.sentenceId;const lemma=w.text.toLowerCase(),entry=vocabulary[lemma]||state.notes[lemma];modal(w.text,'<p style="font:16px Georgia">'+esc(entry?.[0]||'')+'</p><p><strong>'+esc(entry?.[1]||'本地词库暂无此词的可靠释义。')+'</strong></p><p>'+esc(entry?.[2]||'可以记录自己的语境释义；未接入在线词典，不会编造解释。')+'</p><blockquote style="margin:15px 0;padding-left:12px;border-left:2px solid var(--line);font-family:Georgia">'+esc(s.englishText)+'</blockquote><button class="primary" data-action="word-audio" '+(w.startTime===null?'disabled':'')+'>▷ 听原声中的这个词</button><button data-action="note-word">编辑我的词汇笔记</button><p>该词时间来自自动对齐。未人工校准前，连读边界可能包含相邻音素。</p>');}
