function editWord(){const {s,w}=selectedWord(activeWordKey);if(!w)return;modal('词汇笔记 · '+w.text,'<textarea id="word-note" maxlength="6000" placeholder="词性、语境含义、常见搭配…">'+esc(state.notes[w.text.toLowerCase()]?.[1]||'')+'</textarea><div class="modal-actions"><button class="primary" data-action="save-word">保存到本机</button></div>');}
function calibration(id){const s=passage().sentences.find(s=>s.sentenceId===id);modal('校准单句范围','<p>'+esc(s.englishText)+'</p><p>相对于本篇正文音频的秒数。试听包含当前设置的起播前导；保存的边界仍为下方输入值。不要按字数平均分配时间。</p><label>开始 <input type="number" min="0" step="0.01" id="cal-start" value="'+(s.startTime??0)+'"></label>　<label>结束 <input type="number" min="0" step="0.01" id="cal-end" value="'+(s.endTime??1)+'"></label><div class="modal-actions"><button data-cal-preview="'+id+'">试听此范围</button><button class="primary" data-cal-save="'+id+'">确认试听并保存</button></div>');}
